  // 4) 아까 들은 음악은 내가 좋아하는 음악이에요.
  // 5) 이 케이크는 오늘 아침에 만든 거예요.
  //
  // 연습 2
  // [보기]
  // 어제 친구를 만났어요.
  // + 그 친구는 은행에서 일하고 있어요.
  // → 어제 만난 친구는 은행에서 일하고 있어요.
  //
  // 1) 지난번에 간 식당이 참 좋았어요.
  // 2) 친구가 마신 차는 녹차예요.
  // 3) 어제 읽은 책이 너무 슬펐어요.
  // 4) 어제 산 지갑을 오늘 잃어버렸어요.
  //
  // 교재 p.35 연습 3
  // [보기] 오늘 아침에 커피를 마시다
  // → 오늘 아침에 커피를 마신 사람은
  //    마리코 씨와 히엔 씨예요.
  //
  // 1) 지난주에 명동에 가다
  // 2) 오늘 학교에 지하철을 타고 오다
  // 3) 지난 주말에 쇼핑을 하다
  // 4) 오늘 숙제를 안 내다
  // 5) 오늘 아침을 안 먹다
  // 6) 어제 집에서 음식을 만들다
  // 7) 자유 질문
  //
  // ※ 1~7의 사람 이름은 교재에서 학습자가 직접 인터뷰해
