  // ══════════════════════════════════════════════════════════
  // Node 5 · 하지 않아요
  // A/V-지 않다
  //
  // 교재 p.36~37
  //
  // p.36 연습 1
  // [보기]
  // 오늘은 학교에 안 가요.
  // → 오늘은 학교에 가지 않아요.
  //
  // 1) 제 방은 안 커요.
  //    → 제 방은 크지 않아요.
  //
  // 2) 사람들이 별로 안 많아요.
  //    → 사람들이 별로 많지 않아요.
  //
  // 3) 아키라 씨는 요즘 안 바빠요.
  //    → 아키라 씨는 요즘 바쁘지 않아요.
  //
  // 4) 그 책은 안 어려워요.
  //    → 그 책은 어렵지 않아요.
  //
  // 5) 저는 공부하면서 음악을 안 들어요.
  //    → 저는 공부하면서 음악을 듣지 않아요.
  //
  // 6) 저는 매운 음식을 안 좋아해요.
  //    → 저는 매운 음식을 좋아하지 않아요.
  //
  // 7) 어제는 커피를 안 마셨어요.
  //    → 어제는 커피를 마시지 않았어요.
  //
  // 8) 내일부터 학교에 안 늦을 거예요.
  //    → 내일부터 학교에 늦지 않을 거예요.
  //
  // p.36 연습 2
  // [보기]
  // A: 어제 학교에 갔어요?
  // B: 아니요, 아파서 가지 못했어요.
  //
  // 1) 점심 먹었어요?
  //    → 시간이 없어서 먹지 못했어요.
  //
  // 2) 오늘 배운 문법 다 이해했어요?
  //    → 어려워서 이해하지 못했어요.
  //
  // 3) 선생님 만났어요?
  //    → 선생님이 안 계셔서 만나지 못했어요.
  //
  // 4) 조금 전에 샤오밍 씨가 하는 말 들었어요?
  //    → 음악이 너무 시끄러워서 듣지 못했어요.
  //
  // p.37 연습 3
  // [보기]
  // A: 김치가 많이 매워요?
  // B: 아니요, 별로 맵지 않아요.
  //
  // 그림 상황
  // 1) 지하철에 사람이 많아요?
  // 2) 지금 배고파요?
  // 3) 요즘 날씨가 추워요?
  // 4) 어제 시험은 어려웠어요?
  // 5) 어제 공부 많이 했어요?
  // 6) 자유 질문
  //
  // Grammar 전용 문제 타입 사용 금지.
  // ══════════════════════════════════════════════════════════

  // ──────────────────────────────────────────────────────────
  // Node 5 · Lesson 1
  // 안 해요 → 하지 않아요
  // ──────────────────────────────────────────────────────────

